        heading1: "Về WireGuard",
        p1: "WireGuard là một giao thức VPN hiện đại, hiệu năng cao sử dụng mật mã học tiên tiến. Nó được thiết kế để đơn giản và nhanh hơn các giao thức cũ như OpenVPN và IPsec, với bề mặt tấn công nhỏ hơn nhiều nhờ codebase tối giản. WireGuard hiện đã là một phần của nhân Linux và được hỗ trợ gốc trên Windows, macOS, iOS và Android.",
        heading2: "Cách sử dụng công cụ này",
        p2: "Chọn một mẫu cấu trúc liên kết (Point-to-Point, Hub-and-Spoke, Site-to-Site, hoặc Road Warrior) để điền sẵn cấu hình. Nhấp Tạo khóa để tạo cặp khóa mới cục bộ trong trình duyệt của bạn. Điền các trường bắt buộc và nhấp Tạo cấu hình để tạo tệp cấu hình WireGuard. Dùng Tải xuống .conf để lưu tệp hoặc Tạo mã QR để tạo mã QR nhập trên di động.",
        heading3: "Trường hợp sử dụng phổ biến",
        p3: "VPN truy cập từ xa cho nhân viên kết nối vào mạng công ty. VPN site-to-site để kết nối mạng các văn phòng chi nhánh. Máy chủ VPN cá nhân để duyệt web an toàn trên Wi-Fi công cộng. Tunneling thiết bị IoT để giao tiếp an toàn giữa các thiết bị nhúng.",
        heading4: "Mẹo hay",
        p4: "Sử dụng PersistentKeepalive = 25 trên các client sau NAT để duy trì tunnel khi không có lưu lượng đi qua. PresharedKey thêm một lớp mã hóa đối xứng bổ sung để chống lại tấn công hậu lượng tử. AllowedIPs = 0.0.0.0/0 định tuyến toàn bộ lưu lượng qua tunnel (full tunnel), trong khi các CIDR cụ thể tạo ra split tunnel.",
