        heading1: "Biểu thức chính quy là gì?",
        p1: "Biểu thức chính quy (regex) là các mẫu mạnh mẽ dùng để khớp các tổ hợp ký tự trong chuỗi. Chúng là công cụ thiết yếu để xử lý văn bản, xác thực, và trích xuất dữ liệu trên nhiều ngôn ngữ lập trình. Mẫu regex bao gồm các ký tự chữ và các siêu ký tự đặc biệt định nghĩa quy tắc tìm kiếm. Chúng được dùng trong xác thực biểu mẫu, phân tích log, thao tác tìm và thay thế, và các tác vụ làm sạch dữ liệu.",
        heading2: "Cách sử dụng công cụ này",
        p2: "Nhập mẫu regex của bạn vào ô nhập liệu. Công cụ sẽ tự động tạo sơ đồ railroad trực quan hóa cấu trúc mẫu. Thêm văn bản kiểm tra để xem việc tô sáng kết quả khớp và giải thích theo thời gian thực. Dùng bảng tham khảo nhanh để tra cứu các mẫu và cú pháp phổ biến. Tạo đoạn mã cho ngôn ngữ lập trình bạn ưa thích.",
