        p1: "Unix time (còn gọi là Epoch time, POSIX time hoặc Unix timestamp) là hệ thống mô tả một thời điểm cụ thể. Đây là số giây đã trôi qua kể từ Unix Epoch, trừ giây nhuận; Unix Epoch là 00:00:00 UTC ngày 1 tháng 1 năm 1970. Nó được sử dụng rộng rãi trong hệ điều hành và định dạng tệp vì là một số nguyên đơn, giúp máy tính dễ dàng lưu trữ và xử lý. Tiêu chuẩn này cho phép các hệ thống khác nhau truyền đạt thời gian chính xác bất kể cài đặt múi giờ địa phương.",
