        p1: "<p>Mô hình màu sắc là các hệ thống toán học để biểu diễn màu sắc. <strong>HEX</strong> (Thập lục phân) là mã 6 chữ số dùng trong HTML và CSS, đại diện cho các thành phần Đỏ, Xanh lá và Xanh dương. <strong>RGB</strong> (Đỏ, Xanh lá, Xanh dương) sử dụng giá trị thập phân từ 0 đến 255 cho mỗi kênh, thường dùng trong hình ảnh kỹ thuật số.</p><p><strong>HSL</strong> (Sắc độ, Độ bão hòa, Độ sáng) trực quan hơn với con người, vì nó mô tả màu sắc theo màu cơ bản (Hue), cường độ (Saturation) và độ sáng (Lightness). Hiểu các mô hình này giúp chọn đúng định dạng cho nhu cầu thiết kế và phát triển, đảm bảo tính nhất quán trên các nền tảng và thiết bị khác nhau.</p>",
