        text0: "Nhập mức giá để tính chi phí",
        desc0: "Việc token hóa khác nhau tùy theo mô hình. Công cụ này ước tính token bằng phương pháp heuristic dựa trên byte/ký tự; hãy dùng nó để lập kế hoạch và dự toán ngân sách, không phải để tính hóa đơn chính xác.",
        desc2: "Văn bản không phải ASCII (Hàn/Nhật), mã, và JSON thường được token hóa khác với tiếng Anh thuần.",
