      edu: {
        heading1: "Về việc đếm Token",
        p1: "Token là đơn vị cơ bản mà các mô hình ngôn ngữ lớn xử lý. Một token tương đương khoảng 4 ký tự hoặc 0.75 từ trong tiếng Anh, nhưng thay đổi đáng kể đối với các ngôn ngữ khác, mã, và ký tự đặc biệt. Biết được số lượng token là điều cần thiết để quản lý chi phí API, giữ trong giới hạn context window, và tối ưu hóa hiệu quả prompt.",
        heading2: "Cách sử dụng công cụ này",
        p2: "Dán hoặc gõ văn bản của bạn vào ô nhập liệu. Công cụ sẽ ngay lập tức ước tính số lượng token trên nhiều họ mô hình (GPT, Claude, LLaMA). Chuyển đổi giữa chế độ Tiêu chuẩn và Thận trọng để xem ước tính tốt nhất so với ước tính an toàn. Dùng bảng phân tích chi phí để so sánh giá giữa các mô hình và nhà cung cấp khác nhau.",
        heading3: "Trường hợp sử dụng phổ biến",
        p3: "Tối ưu hóa prompt để đảm bảo prompt của bạn nằm trong giới hạn context của mô hình trước khi gọi API. Ước tính chi phí để dự báo chi tiêu API cho các tác vụ xử lý văn bản quy mô lớn. Lập kế hoạch context window khi xây dựng ứng dụng ghép nhiều tài liệu hoặc lịch sử hội thoại. So sánh giá mô hình để chọn mô hình tiết kiệm chi phí nhất cho khối lượng công việc của bạn.",
        heading4: "Mẹo hay",
        p4: "Văn bản không phải ASCII như tiếng Hàn, Nhật, và Trung thường sử dụng nhiều token hơn trên mỗi ký tự so với tiếng Anh. Mã và JSON có thể được token hóa khác với văn bản thuần. Dùng chế độ Thận trọng khi dự toán ngân sách để tránh vượt mức bất ngờ. Để tính hóa đơn chính xác, hãy dùng tokenizer chính thức của nhà cung cấp khi có sẵn.",
      },
